private ReflectionUtils() {}

public static <T> T getAnnotationProperty(String targetType, String annotationType, String property) throws Exception {
    Class<Annotation> annotationClass = (Class<Annotation>) Class.forName(annotationType);
    Annotation annotation = Class.forName(targetType).getAnnotation(annotationClass);
    return (T) annotationClass.getDeclaredMethod(property).invoke(annotation);
}

@ApiOperation(value = "Update Rule Chain Metadata",
        notes = "Updates the rule chain metadata. " + RULE_CHAIN_METADATA_DESCRIPTION + TENANT_AUTHORITY_PARAGRAPH)
@PreAuthorize("hasAuthority('TENANT_ADMIN')")
@PostMapping("/ruleChain/metadata")
public RuleChainMetaData saveRuleChainMetaData(
        @Parameter(description = "A JSON value representing the rule chain metadata.")
        @RequestBody RuleChainMetaData ruleChainMetaData,
        @Parameter(description = "Update related rule nodes.")
        @RequestParam(value = "updateRelated", required = false, defaultValue = "true") boolean updateRelated
) throws Exception {
    TenantId tenantId = getTenantId();
    if (debugPerTenantEnabled) {
        ConcurrentMap<TenantId, DebugTbRateLimits> debugPerTenantLimits = actorContext.getDebugPerTenantLimits();
        DebugTbRateLimits debugTbRateLimits = debugPerTenantLimits.getOrDefault(tenantId, null);
        if (debugTbRateLimits != null) {
            debugPerTenantLimits.remove(tenantId, debugTbRateLimits);
        }
    }
    RuleChain ruleChain = checkRuleChain(ruleChainMetaData.getRuleChainId(), Operation.WRITE);

    return tbRuleChainService.saveRuleChainMetaData(tenantId, ruleChain, ruleChainMetaData, updateRelated, getCurrentUser());
}

public static Throwable validateRuleNode(RuleNode ruleNode) {
    String errorPrefix = "'" + ruleNode.getName() + "' node configuration is invalid: ";
    ConstraintValidator.validateFields(ruleNode, errorPrefix);
    Object nodeConfig;
    try {
        Class<Object> nodeConfigType = ReflectionUtils.getAnnotationProperty(ruleNode.getType(),
                "org.thingsboard.rule.engine.api.RuleNode", "configClazz");
        nodeConfig = JacksonUtil.treeToValue(ruleNode.getConfiguration(), nodeConfigType);
    } catch (Throwable t) {
        log.warn("Failed to validate node configuration: {}", ExceptionUtils.getRootCauseMessage(t));
        return t;
    }
    ConstraintValidator.validateFields(nodeConfig, errorPrefix);
    return null;
}

